insert into public.products (slug, category, brand, collection, name, material, style, color, price, description, features, image_path, sort_order, is_available) values
('papa-carlo-idoors-dveri-prykhovanoho-montazhu-papa-karlo-prime-als-zovnishnie-vidkryttia', 'interior', 'Papa Carlo', 'iDoors', 'Papa Carlo Prime-AL(С) Зовнішнє відкриття', 'Міжкімнатні', 'Прихований монтаж', 'Варіанти виконання', 'Ціна за запитом', 'Papa Carlo Prime-AL(С) Зовнішнє відкриття — приховані міжкімнатні двері: глуха модель, для зовнішнього відкривання. Алюмінієвий прихований короб і поліпропіленове покриття Renolit (Німеччина) допомагають створити лаконічний інтер''єр. Актуальну комплектацію й ціну уточнюйте у менеджера.', '["Фабрика Papa Carlo","Колекція iDoors"]', 'https://papa-karlo.com.ua/content/images/5/869x1800l80mc0/dveri-prykhovanoho-montazhu-papa-karlo-prime-als-zovnishnie-vidkryttia-99119444288435.jpg', '950', 'true'),
